True def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    centers = [(r, c) for r in range(1, h - 1) for c in range(1, w - 1)
               if grid[r][c] == 0 and grid[r-1][c] == grid[r+1][c] == grid[r][c-1] == grid[r][c+1] == 2]
    for r, c in centers:
        for axis in (0, 1):
            aligned = [p for p in centers if p != (r, c) and p[axis] == (r, c)[axis]]
            aligned.sort(key=lambda p: p[1-axis])
            before = [p for p in aligned if p[1-axis] < (r, c)[1-axis]]
            after = [p for p in aligned if p[1-axis] > (r, c)[1-axis]]
            for q in ([before[-1]] if before else []) + ([after[0]] if after else []):
                if axis == 0:
                    for y in range(min(c, q[1]) + 2, max(c, q[1]) - 1):
                        out[r][y] = 1
                else:
                    for x in range(min(r, q[0]) + 2, max(r, q[0]) - 1):
                        out[x][c] = 1
    return out
